    //            "bankruptPrice": 1000000.0, //Bankruptcy price
    //            "realisedCost": 0.00000271, //Currently accumulated realised
    //            position value "markValue": 0.00251640, //Mark value
    //            "posInit": 0.00266375, //Position margin
