    //            "maintMargin": 0.00252044, //Position margin
    //            "realLeverage": 1.06, //Leverage of the order
    //            "changeReason": "positionChange",
    //            //changeReason:marginChange、positionChange、liquidation、autoAppendMarginStatusChange、adl
    //            "currentCost": 0.00266375, //Current position value
    //            "openingTimestamp": 1558433191000, //Open time
    //            "currentQty": -20, //Current position
    //            "delevPercentage": 0.52, //ADL ranking percentile
    //            "currentComm": 0.00000271, //Current commission
    //            "realisedGrossCost": 0E-8, //Accumulated reliased gross profit
    //            value "isOpen": true, //Opened position or not
    //            "posCross": 1.2E-7, //Manually added margin
