  virtual void handleSubject(ccxt::any client, ccxt::any message) {
    //
    //     {
    //         "type":"message",
    //         "topic":"/market/level2:BTC-USDT",
    //         "subject":"trade.l2update",
    //         "data":{
    //             "sequenceStart":1545896669105,
    //             "sequenceEnd":1545896669106,
    //             "symbol":"BTC-USDT",
    //             "changes": {
    //                 "asks": [["6","1","1545896669105"]], // price, size,
    //                 sequence "bids": [["4","1","1545896669106"]]
    //             }
    //         }
    //     }
    //
    ccxt::any topic = this->safeString(message, std::string("topic"));
    if (isTrue(isEqual(topic, std::string("/market/ticker:all")))) {
      this->handleTicker(client, message);
      return;
    }
    ccxt::any subject =
        this->safeString2(message, std::string("subject"), std::string("T"));
    ccxt::any methods = ccxt::dict{
        {std::string("level1"), std::string("handleBidAsk")},
        {std::string("level2"), std::string("handleOrderBook")},
        {std::string("trade.l2update"), std::string("handleOrderBook")},
        {std::string("trade.ticker"), std::string("handleTicker")},
        {std::string("trade.snapshot"), std::string("handleTicker")},
        {std::string("trade.l3match"), std::string("handleTrade")},
        {std::string("trade.candles.update"), std::string("handleOHLCV")},
        {std::string("account.balance"), std::string("handleBalance")},
        {std::string("orderChange"), std::string("handleOrder")},
        {std::string("stopOrder"), std::string("handleOrder")},
        {std::string("/spot/tradeFills"), std::string("handleMyTrade")},
        {std::string("ticker"), std::string("handleTicker")},
        {std::string("tickerV2"), std::string("handleBidAsk")},
        {std::string("candle.stick"), std::string("handleOHLCV")},
        {std::string("match"), std::string("handleTrade")},
        {std::string("orderUpdated"), std::string("handleOrder")},
        {std::string("symbolOrderChange"), std::string("handleOrder")},
        {std::string("availableBalance.change"), std::string("handleBalance")},
        {std::string("walletBalance.change"), std::string("handleBalance")},
        {std::string("position.change"), std::string("handlePosition")},
        {std::string("position.settlement"), std::string("handlePosition")},
        {std::string("position.adjustRiskLimit"),
         std::string("handlePosition")},
        {std::string("ticker.SPOT"), std::string("handleUtaTicker")},
        {std::string("ticker.FUTURES"), std::string("handleUtaTicker")},
        {std::string("trade.SPOT"), std::string("handleUtaTrade")},
        {std::string("trade.FUTURES"), std::string("handleUtaTrade")},
        {std::string("kline.SPOT"), std::string("handleUtaOHLCV")},
        {std::string("kline.FUTURES"), std::string("handleUtaOHLCV")},
        {std::string("obu.SPOT"), std::string("handleUtaOrderBook")},
        {std::string("obu.FUTURES"), std::string("handleUtaOrderBook")},
        {std::string("order.UNIFIED"), std::string("handleUtaOrder")},
        {std::string("order.SPOT"), std::string("handleUtaOrder")},
        {std::string("order.FUTURES"), std::string("handleUtaOrder")},
        {std::string("order.CROSS"), std::string("handleUtaOrder")},
        {std::string("order.ISOLATED"), std::string("handleUtaOrder")},
        {std::string("orderAll.UNIFIED"), std::string("handleUtaOrder")},
        {std::string("orderAll.SPOT"), std::string("handleUtaOrder")},
        {std::string("orderAll.FUTURES"), std::string("handleUtaOrder")},
        {std::string("orderAll.CROSS"), std::string("handleUtaOrder")},
        {std::string("orderAll.ISOLATED"), std::string("handleUtaOrder")},
        {std::string("execution.UNIFIED"), std::string("handleUtaMyTrade")},
        {std::string("execution.SPOT"), std::string("handleUtaMyTrade")},
        {std::string("execution.FUTURES"), std::string("handleUtaMyTrade")},
        {std::string("execution.CROSS"), std::string("handleUtaMyTrade")},
        {std::string("execution.ISOLATED"), std::string("handleUtaMyTrade")},
        {std::string("execution.lite.UNIFIED"),
         std::string("handleUtaMyTrade")},
        {std::string("execution.lite.SPOT"), std::string("handleUtaMyTrade")},
        {std::string("execution.lite.FUTURES"),
         std::string("handleUtaMyTrade")},
        {std::string("execution.lite.CROSS"), std::string("handleUtaMyTrade")},
        {std::string("execution.lite.ISOLATED"),
         std::string("handleUtaMyTrade")},
        {std::string("position.UNIFIED"), std::string("handleUtaPosition")},
        {std::string("position.FUTURES"), std::string("handleUtaPosition")},
        {std::string("positionAll.UNIFIED"), std::string("handleUtaPosition")},
        {std::string("positionAll.FUTURES"), std::string("handleUtaPosition")},
        {std::string("balance.UNIFIED"), std::string("handleUtaBalance")},
        {std::string("funding-fee"), std::string("handleUtaFundingRate")},
        {std::string("mark-price"), std::string("handleUtaTicker")},
    };
    ccxt::any method = this->safeValue(methods, subject);
    if (isTrue(!isEqual(method, ccxt::any{}))) {
      this->dispatchMethodName(method, ccxt::list{client, message});
    }
  }

  ccxt::any ping(ccxt::any client) override {
    // kucoin does not support built-in ws protocol-level ping-pong
    // instead it requires a custom json-based text ping-pong
    // https://docs.kucoin.com/#ping
    ccxt::any id = toString(this->requestId());
    return ccxt::dict{
        {std::string("id"), id},
        {std::string("type"), std::string("ping")},
    };
  }

  virtual void handlePong(ccxt::any client, ccxt::any message) {
    ::getValue(client, std::string("lastPong")) = this->milliseconds();
  }

  virtual ccxt::any handleErrorMessage(ccxt::any client, ccxt::any message) {
    //
    //    {
    //        "id": "1",
    //        "type": "error",
    //        "code": 415,
    //        "data": "type is not supported"
    //    }
    //
    // uta
    //     {
    //         "id": "1",
    //         "result": false,
    //         "reason": "missing `symbol` for topic: Position"
    //     }
    //
    ccxt::any data = this->safeString2(message, std::string("data"),
                                      std::string("reason"), std::string(""));
    if (isTrue(isEqual(data, std::string("token is expired")))) {
      ccxt::any type = std::string("public");
      if (isTrue(isGreaterThanOrEqual(
              getIndexOf(::getValue(client, std::string("url")),
                         std::string("connectId=private")),
              0))) {
        type = std::string("private");
      }
      ::setValue(::getValue(this->options, std::string("urls")), type,
                 ccxt::any{});
    }
    this->handleErrors(1, std::string(""),
                       ::getValue(client, std::string("url")), std::string(""),
                       ccxt::dict{}, data, message, ccxt::dict{}, ccxt::dict{});
    return false;
  }

  void handleMessage(ccxt::any client, ccxt::any message) override {
    ccxt::any type =
        this->safeString2(message, std::string("type"), std::string("message"));
    ccxt::any methods = ccxt::dict{
        {std::string("welcome"), std::string("handleSystemStatus")},
        {std::string("ack"), std::string("handleSubscriptionStatus")},
        {std::string("message"), std::string("handleSubject")},
        {std::string("pong"), std::string("handlePong")},
        {std::string("error"), std::string("handleErrorMessage")},
    };
    ccxt::any method = this->safeValue(methods, type);
    if (isTrue(!isEqual(method, ccxt::any{}))) {
      this->dispatchMethodName(method, ccxt::list{client, message});
    } else if (isTrue(inOp(message, std::string("T")))) {
      this->handleSubject(client, message);
    } else if (isTrue(inOp(message, std::string("result")))) {
      ccxt::any result = this->safeBool(message, std::string("result"), true);
      if (isTrue(!isEqual(result, true))) {
        this->handleErrorMessage(client, message);
      }
      this->handleSubscriptionStatus(client, message);
    }
  }

  virtual ccxt::any getMessageHash(ccxt::any elementName,
                                  ccxt::any symbol = ccxt::any{}) {
    // method from kucoinfutures
    // elementName can be 'ticker', 'bidask', ...
    if (isTrue(!isEqual(symbol, ccxt::any{}))) {
      return add(add(elementName, std::string(":")), symbol);
    } else {
      return add(elementName, std::string("s@all"));
    }
  }
